64	func getExpFunc(ctx *sql.Context, vr types.ValueReader, sch schema.Schema, exp sql.Expression) (ExpressionFunc, error) {
65		switch typedExpr := exp.(type) {
66		case *expression.Equals:
67			return newComparisonFunc(ctx, EqualsOp{}, typedExpr, sch)
68		case *expression.GreaterThan:
69			return newComparisonFunc(ctx, GreaterOp{vr}, typedExpr, sch)
70		case *expression.GreaterThanOrEqual:
71			return newComparisonFunc(ctx, GreaterEqualOp{vr}, typedExpr, sch)
72		case *expression.LessThan:
73			return newComparisonFunc(ctx, LessOp{vr}, typedExpr, sch)
74		case *expression.LessThanOrEqual:
75			return newComparisonFunc(ctx, LessEqualOp{vr}, typedExpr, sch)
76		case *expression.Or:
77			leftFunc, err := getExpFunc(ctx, vr, sch, typedExpr.Left())
78	
79			if err != nil {
80				return nil, err
81			}
82	
83			rightFunc, err := getExpFunc(ctx, vr, sch, typedExpr.Right())
84	
85			if err != nil {
86				return nil, err
87			}
88	
89			return newOrFunc(leftFunc, rightFunc), nil
90		case *expression.And:
91			leftFunc, err := getExpFunc(ctx, vr, sch, typedExpr.Left())
92	
93			if err != nil {
94				return nil, err
95			}
96	
97			rightFunc, err := getExpFunc(ctx, vr, sch, typedExpr.Right())
98	
99			if err != nil {
100				return nil, err
101			}
102	
103			return newAndFunc(leftFunc, rightFunc), nil
104		case *expression.InTuple:
105			return newComparisonFunc(ctx, EqualsOp{}, typedExpr, sch)
106		case *expression.Not:
107			expFunc, err := getExpFunc(ctx, vr, sch, typedExpr.Child)
108			if err != nil {
109				return nil, err
110			}
111			return newNotFunc(expFunc), nil
112		case *expression.IsNull:
113			return newComparisonFunc(ctx, EqualsOp{}, expression.NewNullSafeEquals(typedExpr.Child, expression.NewLiteral(nil, gmstypes.Null)), sch)
114		}
115	
116		return nil, errNotImplemented.New(exp.Type().String())
117	}
118	
119	func newOrFunc(left ExpressionFunc, right ExpressionFunc) ExpressionFunc {
120		return func(ctx context.Context, vals map[uint64]types.Value) (b bool, err error) {
121			lRes, err := left(ctx, vals)
122	
123			if err != nil {
124				return false, err
125			}
126	
127			if lRes {
128				return true, nil
129			}
130	
131			return right(ctx, vals)
132		}
133	}
134	
135	func newAndFunc(left ExpressionFunc, right ExpressionFunc) ExpressionFunc {
136		return func(ctx context.Context, vals map[uint64]types.Value) (b bool, err error) {
137			lRes, err := left(ctx, vals)
138	
139			if err != nil {
140				return false, err
141			}
142	
143			if !lRes {
144				return false, nil
145			}
146	
147			return right(ctx, vals)
148		}
149	}
150	
151	func newNotFunc(exp ExpressionFunc) ExpressionFunc {
152		return func(ctx context.Context, vals map[uint64]types.Value) (b bool, err error) {
153			res, err := exp(ctx, vals)
154			if err != nil {
155				return false, err
156			}
157	
158			return !res, nil
159		}
160	}
